-- Initial schema: the spec's data model (docs/spec.md, "Data model (SQLite)").
--
-- Conventions for every migration:
--   * IDs are TEXT UUIDs generated by whoever creates the row (the phone, for page IDs, so they
--     double as idempotency keys). audit_log uses an integer rowid because nothing refers to it.
--   * Timestamps are INTEGER unix milliseconds (UTC). Integers compare and index cheaply for the
--     expiry sweeps (tombstones, enrollment codes, audit retention), cannot be mis-formatted, and
--     map straight to time.UnixMilli in Go.
--   * Booleans are INTEGER 0/1 with a CHECK.
--   * Tables are STRICT so SQLite rejects values of the wrong type instead of coercing them.
--   * Hashes and opaque client-signed payloads are BLOBs; the server never parses envelopes.
--   * Migrations are expand-then-contract (spec, "Server deploys"), so CHECK constraints are kept
--     to values the spec fixes: SQLite can only change a CHECK by rebuilding the table.

-- +goose Up
CREATE TABLE users (
  id           TEXT    NOT NULL PRIMARY KEY,
  display_name TEXT    NOT NULL CHECK (display_name <> ''),
  is_admin     INTEGER NOT NULL DEFAULT 0 CHECK (is_admin IN (0, 1)),
  created_at   INTEGER NOT NULL
) STRICT;

CREATE TABLE devices (
  id               TEXT    NOT NULL PRIMARY KEY,
  user_id          TEXT    NOT NULL REFERENCES users (id),
  name             TEXT    NOT NULL,
  -- SHA-256 of the 256-bit bearer token; the token itself is never stored.
  token_hash       BLOB    NOT NULL UNIQUE CHECK (length(token_hash) = 32),
  -- NULL until the phone registers with FCM; replaced whenever FCM rotates it.
  fcm_token        TEXT,
  app_version      TEXT,
  -- Latest setup-checklist report from the phone (JSON), used by the heartbeat alerts.
  checklist_status TEXT,
  created_at       INTEGER NOT NULL,
  last_seen_at     INTEGER,
  -- Devices are revoked, never deleted, so the audit trail and roster history stay intact.
  revoked_at       INTEGER,
  -- Pre-provisioned smoke-test devices: hidden from contacts and absent from the family roster.
  is_test          INTEGER NOT NULL DEFAULT 0 CHECK (is_test IN (0, 1))
) STRICT;

CREATE INDEX devices_user_id ON devices (user_id);

CREATE TABLE enrollment_codes (
  -- SHA-256 of the one-time 128-bit code.
  code_hash         BLOB    NOT NULL PRIMARY KEY CHECK (length(code_hash) = 32),
  display_name      TEXT    NOT NULL CHECK (display_name <> ''),
  make_admin        INTEGER NOT NULL DEFAULT 0 CHECK (make_admin IN (0, 1)),
  -- NULL for codes minted over SSH by `pttd admin bootstrap`.
  created_by_device TEXT REFERENCES devices (id) ON DELETE SET NULL,
  created_at        INTEGER NOT NULL,
  expires_at        INTEGER NOT NULL,
  used_at           INTEGER
) STRICT;

CREATE INDEX enrollment_codes_created_by_device ON enrollment_codes (created_by_device);
CREATE INDEX enrollment_codes_expires_at ON enrollment_codes (expires_at);

-- Only the latest signed roster is kept; the CHECK on id makes this a single-row table, so a
-- publish is an upsert on id = 1 guarded by the version check.
CREATE TABLE roster (
  id            INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
  version       INTEGER NOT NULL CHECK (version > 0),
  signed_roster BLOB    NOT NULL,
  signer_device TEXT    NOT NULL REFERENCES devices (id),
  updated_at    INTEGER NOT NULL
) STRICT;

CREATE INDEX roster_signer_device ON roster (signer_device);

-- Pages exist only while ringing or in conversation; ended pages are deleted and leave a
-- tombstone. The state machine lives in Go, so state is not constrained here.
CREATE TABLE active_pages (
  id            TEXT    NOT NULL PRIMARY KEY,
  session_id    TEXT    NOT NULL,
  from_device   TEXT    NOT NULL REFERENCES devices (id),
  to_user       TEXT    NOT NULL REFERENCES users (id),
  level         TEXT    NOT NULL CHECK (level IN ('normal', 'urgent')),
  -- Sender-signed envelope with the wrapped session keys; opaque to the server.
  envelope      BLOB    NOT NULL,
  state         TEXT    NOT NULL,
  created_at    INTEGER NOT NULL,
  delivered_at  INTEGER,
  push_attempts INTEGER NOT NULL DEFAULT 0 CHECK (push_attempts >= 0)
) STRICT;

CREATE INDEX active_pages_session_id ON active_pages (session_id);
CREATE INDEX active_pages_from_device ON active_pages (from_device);
CREATE INDEX active_pages_to_user ON active_pages (to_user);

-- Idempotency tombstones for ended pages (24 h). Deliberately no other columns: once a page
-- ends, nothing records who paged whom.
CREATE TABLE page_tombstones (
  id         TEXT    NOT NULL PRIMARY KEY,
  expires_at INTEGER NOT NULL
) STRICT;

CREATE INDEX page_tombstones_expires_at ON page_tombstones (expires_at);

-- Enrollment, revocation, roster changes, and auth failures only; kept 90 days.
CREATE TABLE audit_log (
  id           INTEGER NOT NULL PRIMARY KEY,
  at           INTEGER NOT NULL,
  -- NULL for SSH admin CLI actions and for auth failures from unknown devices.
  actor_device TEXT REFERENCES devices (id) ON DELETE SET NULL,
  action       TEXT    NOT NULL CHECK (action <> ''),
  -- Event-specific JSON.
  detail       TEXT
) STRICT;

CREATE INDEX audit_log_at ON audit_log (at);
CREATE INDEX audit_log_actor_device ON audit_log (actor_device);

-- +goose Down
DROP TABLE audit_log;
DROP TABLE page_tombstones;
DROP TABLE active_pages;
DROP TABLE roster;
DROP TABLE enrollment_codes;
DROP TABLE devices;
DROP TABLE users;
